// Safely retrieve data from all upstream nodes
const input      = $('Extract Input').first().json;
const customers  = $('Query Customer Data').all().map(i => i.json);
const knowledge  = (() => { try { return $('Search Knowledge Base').all().map(i => i.json); } catch(e) { return []; } })();

const message    = input.message    || '';
const session_id = input.session_id || 'session-' + Date.now();
const topic      = input.topic      || 'general';

// ── Customer stats ──────────────────────────────────────────────────────────
const total     = customers.length;
const revenue   = customers.reduce((s, c) => s + (parseFloat(c.amount_spent) || 0), 0);
const rebooked  = customers.filter(c => c.rebooked === true || c.rebooked === 'true').length;
const avgSat    = total > 0
  ? (customers.reduce((s, c) => s + (parseFloat(c.satisfaction_score) || 0), 0) / total).toFixed(1)
  : 'N/A';

const treatments = {};
customers.forEach(c => { treatments[c.treatment || 'Unknown'] = (treatments[c.treatment || 'Unknown'] || 0) + 1; });
const treatList = Object.entries(treatments).map(([k, v]) => `  • ${k}: ${v} clients`).join('\n');

const topCustomers = customers.slice(0, 8)
  .map(c => `  - ${c.name}: ${c.treatment}, $${c.amount_spent}, last visit: ${c.last_visit}, rebooked: ${c.rebooked ? 'Yes' : 'No'}, satisfaction: ${c.satisfaction_score}`)
  .join('\n');

const customerContext = total > 0
  ? `CUSTOMER DATA (${total} records):
• Revenue total: $${revenue.toFixed(2)} | Rebook rate: ${((rebooked/total)*100).toFixed(1)}% | Avg satisfaction: ${avgSat}
• Treatment breakdown:
${treatList}

Recent customers:
${topCustomers}`
  : 'No customer records yet. Seed the database to enable data-driven coaching.';

// ── Knowledge base context ───────────────────────────────────────────────────
const kbContext = knowledge.length > 0
  ? 'KNOWLEDGE BASE:\n' + knowledge.map((c, i) => `[${i+1}] ${c.content || ''}`).join('\n\n')
  : 'No knowledge documents uploaded yet.';

// ── Topic instructions ───────────────────────────────────────────────────────
const topics = {
  retention:  'Analyse rebook rates and satisfaction scores. Give specific retention strategies and follow-up recommendations.',
  sales:      'Analyse conversion rates and revenue data. Give actionable sales coaching and objection-handling advice.',
  knowledge:  'Reference clinic documents, SOPs, and policies to answer operational questions.',
  general:    'Provide holistic business coaching using all available data.'
};
const topicGuide = topics[topic] || topics.general;

const system_prompt = `You are an expert AI Business Coach for an aesthetic clinic owner.
Focus: ${topic.toUpperCase()} — ${topicGuide}

${customerContext}

${kbContext}

Rules:
- Be SPECIFIC. Reference actual customer names, numbers, and percentages.
- Give 2-3 concrete, actionable next steps at the end.
- Be concise (150-350 words). Professional but warm tone.`;

return [{ json: { message, session_id, topic, system_prompt } }];

